WITH valid_departments AS (SELECT * FROM departments WHERE budget < 2225000), departments_stats AS (SELECT CASE WHEN budget >= 4403000 THEN 'high' WHEN budget >= 898000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(budget) AS budget_count, COUNT(CASE WHEN dept_name = 'HR' THEN 1 END) AS hr_count FROM valid_departments GROUP BY CASE WHEN budget >= 4403000 THEN 'high' WHEN budget >= 898000 THEN 'mid' ELSE 'low' END) SELECT * FROM departments_stats WHERE budget_count >= 6;
